package com.drogaria.backend.service;
import com.drogaria.backend.dto.EnderecoRequest; import com.drogaria.backend.entity.Endereco; import com.drogaria.backend.exception.ApiException; import com.drogaria.backend.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.List;
@Service public class EnderecoService { private final EnderecoRepository r; private final ClienteRepository clientes; public EnderecoService(EnderecoRepository r,ClienteRepository c){this.r=r;clientes=c;} public List<Endereco> cliente(Integer id){return r.findByClienteId(id);} public Endereco buscar(Integer id){return r.findById(id).orElseThrow(()->new ApiException("Endereco nao encontrado",HttpStatus.NOT_FOUND));} public Endereco salvar(EnderecoRequest x){Endereco e=new Endereco();preencher(e,x);return r.save(e);} public Endereco atualizar(Integer id,EnderecoRequest x){Endereco e=buscar(id);preencher(e,x);return r.save(e);} private void preencher(Endereco e,EnderecoRequest x){e.setRua(x.getRua());e.setNumero(x.getNumero());e.setBairro(x.getBairro());e.setCidade(x.getCidade());e.setEstado(x.getEstado());e.setCep(x.getCep());e.setCliente(clientes.findById(x.getIdCliente()).orElseThrow(()->new ApiException("Cliente nao encontrado",HttpStatus.NOT_FOUND)));} public void excluir(Integer id){r.deleteById(id);} }